'use strict'
// Full standalone operator binary against a REAL disposable Fabric 1.21.1 JVM.
// Credentials and action grants are prepared by THIS independent lab driver,
// never generated by qa_operator.js. Offline player identity is NOT authenticated.
const crypto=require('node:crypto')
const fs=require('node:fs')
const path=require('node:path')
const os=require('node:os')
const {spawn}=require('node:child_process')
const mineflayer=require('mineflayer')
const {Vec3}=require('vec3')
const {createPinnedQaServerBridgeAuthority}=require('../src/fabric_bridge_reader')
const {createPinnedQaLivePresenceAuthority}=require('../src/live_presence')
const {openQaPrincipalRegistry}=require('../src/principal_enrollment')
const {createQaCheckpointWitness}=require('../src/qa_checkpoint_witness')
const {createPinnedQaRemoteCheckpointClient}=require('../src/remote_checkpoint')
const {openMission}=require('../src/mission')
const {openDepositJournal}=require('../src/deposit')

const [eventsFile,serverPubFile,journalRoot,readyFlag]=process.argv.slice(2)
const worldId='qa:real-fabric:25593',botName='GuiaIA_QA',username='OwnerQA'
const principalId='qa_external_preapproved_owner'
const key=()=>crypto.generateKeyPairSync('ed25519')
const pub=k=>k.publicKey.export({format:'pem',type:'spki'})
const privatePem=k=>k.privateKey.export({format:'pem',type:'pkcs8'})
const signed=(payload,k)=>({payload,signature:crypto.sign(null,
  Buffer.from(JSON.stringify(payload)),k.privateKey).toString('base64url')})
const sleep=ms=>new Promise(r=>setTimeout(r,ms))
const waitUntil=async (predicate,timeout,description)=>{
  const until=Date.now()+timeout
  while(Date.now()<until){if(await predicate())return;await sleep(150)}
  throw Error('QA timed out waiting for '+description)
}
function safeTemp(file,marker){
  const rel=path.relative(os.tmpdir(),file)
  if(typeof file!=='string'||!path.isAbsolute(file)||
     !rel.startsWith('guiaia-fabric-bridge-qa-')||
     !rel.includes(marker))throw Error('Refuse non-disposable test paths')
}
async function main(){
  safeTemp(eventsFile,'events.jsonl')
  safeTemp(serverPubFile,'qa-public.pem')
  safeTemp(journalRoot,'journal')
  safeTemp(readyFlag,'qa-operator-ready.flag')
  if(fs.existsSync(readyFlag))throw Error('QA readiness flag already exists')
  const qaRoot=fs.mkdtempSync(path.join(os.tmpdir(),'guiaia-operator-qa-'))
  const registryRoot=fs.mkdtempSync(path.join(os.tmpdir(),'guiaia-enrollment-qa-'))
  const witnessRoot=fs.mkdtempSync(path.join(os.tmpdir(),'guiaia-remote-anchor-qa-'))
  fs.rmdirSync(witnessRoot)
  const serverPub=fs.readFileSync(serverPubFile,'utf8')
  const source=createPinnedQaServerBridgeAuthority(eventsFile,serverPub,worldId)
  const live=createPinnedQaLivePresenceAuthority({
    port:25594,worldId,serverBridgePublicKeyPem:serverPub})
  const ownerKey=key(),operatorKey=key(),witnessKey=key()
  const witness=createQaCheckpointWitness({
    directory:witnessRoot,worldId,
    operatorPublicKeyPem:pub(operatorKey),witnessPrivateKey:witnessKey.privateKey})
  let owner=null,cli=null,registry=null,mission=null,deposit=null
  let operatorOutput=''
  try{
    const opts={host:'127.0.0.1',port:25593,auth:'offline',
      username,version:'1.21.1',hideErrors:true}
    owner=mineflayer.createBot(opts)
    await new Promise((resolve,reject)=>{
      const timeout=setTimeout(()=>reject(Error('QA owner connection timed out')),20000)
      owner.once('spawn',()=>{clearTimeout(timeout);resolve()})
      owner.once('end',()=>{clearTimeout(timeout);reject(Error('QA owner disconnected'))})
      owner.once('error',()=>{clearTimeout(timeout);reject(Error('QA owner connection refused'))})
    })
    let connectionId,join
    await waitUntil(()=>{
      let state
      try {state=require('../src/fabric_bridge_reader').verifyBridgeLog(
        eventsFile,serverPub,worldId)}
      catch(error){
        // A real JOIN may be concurrently appended; never accept a partial
        // record, but re-read it once the producer has finished writing.
        if(['Truncated bridge event record','Partial bridge audit read',
            'Corrupted bridge event'].includes(error?.message))return false
        throw error
      }
      const current=[...state.active.values()].find(p=>p.username===username)
      if(!current)return false
      connectionId=current.connectionId
      try{
        join=source.joinProof(connectionId)
        return !!join&&source.activeConnection(connectionId)?.connected===true
      }catch(error){
        if(['Truncated bridge event record','Partial bridge audit read',
            'Corrupted bridge event'].includes(error?.message))return false
        throw error
      }
    },20000,'complete actual Fabric-signed JOIN event')
    await waitUntil(async()=>{
      try{return (await live.livePresence(connectionId)).connected===true}
      catch(error){
        if(['Live Fabric server timeout','Live Fabric query unavailable',
          'Stale or mismatched live server evidence'].includes(error?.message))
          return false
        throw error
      }
    },25000,'fresh server-signed presence after warmup')

    registry=openQaPrincipalRegistry(path.join(registryRoot,'registry'),{
      sandboxOnly:true,worldId,operatorPublicKeyPem:pub(operatorKey)})
    const before=registry.exportCheckpoint()
    const now=Date.now()
    const enrollment={aud:'guiaia:principal-enrollment:v1',worldId,principalId,
      nonce:crypto.randomUUID(),issuedAt:now-1000,expiresAt:now+60000,
      publicKeyDer:ownerKey.publicKey.export({format:'der',type:'spki'}).toString('base64url')}
    const consent=crypto.sign(null,Buffer.from(
      'guiaia:principal-consent:v1\n'+JSON.stringify(enrollment)),
      ownerKey.privateKey).toString('base64url')
    if(registry.applySignedChange(signed(enrollment,operatorKey),consent).action!=='enrolled')
      throw Error('QA externally signed enrollment denied')
    const after=registry.exportCheckpoint()
    const witnessUrl=await witness.start()
    const witnessClient=createPinnedQaRemoteCheckpointClient({
      url:witnessUrl,worldId,operatorPublicKeyPem:pub(operatorKey),
      witnessPublicKeyPem:pub(witnessKey)})
    async function advance(a,b){
      const now=Date.now()
      await witnessClient.publish(signed({
        aud:'guiaia:checkpoint-advance:v1',worldId,
        operatorFingerprint:after.operatorFingerprint,
        previousSequence:a===null?-1:a.sequence,
        previousSha256:a===null?null:a.registrySha256,
        sequence:b.sequence,registrySha256:b.registrySha256,
        nonce:crypto.randomUUID(),issuedAt:now-1000,expiresAt:now+30000
      },operatorKey))
    }
    await advance(null,before)
    await advance(before,after)
    await witnessClient.verifyLocal(after)
    registry.close()
    registry=null

    const target={x:7,y:64,z:2},chest={x:4,y:64,z:3}
    const missionDir=path.join(qaRoot,'mission')
    const depositDir=path.join(qaRoot,'deposit')
    mission=openMission(missionDir,{sandboxOnly:true,ownerName:username,
      targets:[{...target,block:'oak_log'}]})
    deposit=openDepositJournal(depositDir,{sandboxOnly:true,ownerName:username,
      chest,items:[{name:'oak_log',count:1}]})
    const approvedPlan={sandboxOnly:true,ownerName:username,
      missionId:mission.view().missionId,planId:deposit.view().planId,
      targets:[{...target,block:'oak_log'}],items:[{name:'oak_log',count:1}],chest}
    mission.close();mission=null
    deposit.close();deposit=null

    const fields={worldId,botName,ownerName:username,principalId,
      connectionId,challenge:join.payload.challenge}
    const times=()=>({nonce:crypto.randomUUID(),
      issuedAt:Date.now()-1000,expiresAt:Date.now()+85000})
    const grants={gather:[signed({
      aud:'guiaia:session-gather:v1',...fields,target,
      item:'oak_log',count:1,...times()},operatorKey)],
      deposit:[signed({
        aud:'guiaia:session-deposit:v1',...fields,chest,
        item:'oak_log',count:1,...times()},operatorKey)],
      followGrant:null}
    const privateFile=(filename,data)=>{
      const full=path.join(qaRoot,filename)
      fs.writeFileSync(full,data,{mode:0o600,flag:'wx'})
      return full
    }
    const ownerPrivate=privateFile('owner-private.pem',privatePem(ownerKey))
    const operatorPublic=privateFile('operator-public.pem',pub(operatorKey))
    const serverPublic=privateFile('server-public.pem',serverPub)
    const witnessPublic=privateFile('witness-public.pem',pub(witnessKey))
    const planFile=privateFile('plan.json',JSON.stringify(approvedPlan))
    const grantsFile=privateFile('grants.json',JSON.stringify(grants))
    const conf={version:1,sandboxOnly:true,worldId,botName,username,
      principalId,connectionId,eventsFile,
      registryDirectory:path.join(registryRoot,'registry'),
      principalPrivateKeyFile:ownerPrivate,operatorPublicKeyFile:operatorPublic,
      serverBridgePublicKeyFile:serverPublic,
      witnessPublicKeyFile:witnessPublic,witnessUrl,
      livePort:25594,missionDirectory:missionDir,depositDirectory:depositDir,
      spentDirectory:path.join(qaRoot,'spent'),
      approvedPlanFile:planFile,grantsFile}
    const configFile=privateFile('config.json',JSON.stringify(conf))
    const command=process.execPath+' '+path.resolve(__dirname,'../qa_operator.js')+
      ' --qa-operate '+configFile
    cli=spawn('script',['-qfec',command,'/dev/null'],{
      cwd:path.resolve(__dirname,'..'),env:{...process.env,TERM:'dumb'},
      stdio:['pipe','pipe','pipe']})
    cli.stdout.setEncoding('utf8')
    cli.stderr.setEncoding('utf8')
    cli.stdout.on('data',text=>{operatorOutput+=text})
    cli.stderr.on('data',text=>{operatorOutput+=text})
    await waitUntil(()=>{
      if(cli.exitCode!==null)throw Error('Standalone QA operator terminated during startup: '+operatorOutput.slice(-900))
      return operatorOutput.includes('"result":"qa_operator_ready"')
    },20000,'operator real TTY bootstrap')
    await waitUntil(()=>fs.existsSync(readyFlag),
      25000,'Minecraft inventory prepared by independent Python driver')
    cli.stdin.write('mision\n')
    await waitUntil(()=>{
      if(cli.exitCode!==null)throw Error('Standalone QA operator stopped mid-mission: '+operatorOutput.slice(-1000))
      return operatorOutput.includes('"phase":"completed"')
    },45000,'real signed gather and deposit via standalone QA operator')
    cli.stdin.write('salir\n')
    await new Promise((resolve,reject)=>{
      const timeout=setTimeout(()=>reject(Error('Operator TTY did not shut down')),10000)
      cli.once('exit',(code)=>{clearTimeout(timeout);code===0?resolve():reject(Error('QA operator exit '+code))})
    })
    cli=null
    const missionResult=JSON.parse(fs.readFileSync(path.join(missionDir,'mission.json')))
    const depositResult=JSON.parse(fs.readFileSync(path.join(depositDir,'deposit.json')))
    const spent=fs.readdirSync(path.join(qaRoot,'spent')).filter(x=>x.endsWith('.used'))
    if(missionResult.phase!=='completed'||missionResult.receipts.length!==1||
       depositResult.phase!=='completed'||depositResult.receipts.length!==1||
       spent.length!==2)throw Error('Signed mission lacked durable receipts or nonce barrier')
    await waitUntil(()=>owner.blockAt(new Vec3(7,64,2))?.name==='air',
      7000,'real oak log physically mined')
    const chestBlock=owner.blockAt(new Vec3(4,64,3))
    if(chestBlock?.name!=='chest')throw Error('World has no physical approved chest')
    const container=await owner.openContainer(chestBlock)
    let chestStock=0
    try{
      for(const slot of container.slots.slice(0,container.inventoryStart))
        if(slot?.name==='oak_log')chestStock+=slot.count
    }finally{container.close()}
    if(chestStock!==1)throw Error('Real chest did not receive exactly one oak log')

    // A separate-process negative test: after the real operation has fully
    // finished, revoke the formerly valid principal, advance the signed
    // witness and attempt the SAME preflight configuration again. It MUST
    // reject the principal before reconnecting a bot or touching the world.
    const missionBytes=fs.readFileSync(path.join(missionDir,'mission.json'))
    const depositBytes=fs.readFileSync(path.join(depositDir,'deposit.json'))
    const usedBefore=spent.length
    registry=openQaPrincipalRegistry(path.join(registryRoot,'registry'),{
      sandboxOnly:true,worldId,operatorPublicKeyPem:pub(operatorKey)})
    const revBefore=registry.exportCheckpoint()
    const revNow=Date.now()
    const revokeTicket=signed({aud:'guiaia:principal-revocation:v1',
      worldId,principalId,nonce:crypto.randomUUID(),
      issuedAt:revNow-1000,expiresAt:revNow+30000},operatorKey)
    const revoked=registry.applySignedChange(revokeTicket)
    if(revoked.action!=='revoked'||registry.isRevoked(principalId)!==true)
      throw Error('Revocation did not become durable')
    const revAfter=registry.exportCheckpoint()
    await advance(revBefore,revAfter)
    if(await witnessClient.verifyLocal(revAfter)!==true)
      throw Error('Witness did not confirm revocation')
    registry.close();registry=null

    const excluded=new Set(['missionDirectory','depositDirectory','spentDirectory',
      'approvedPlanFile','grantsFile'])
    const preflightConfig=Object.fromEntries(Object.entries(conf)
      .filter(([name])=>!excluded.has(name)))
    const preflightFile=privateFile('revoked-preflight.json',
      JSON.stringify(preflightConfig))
    const probe=spawn(process.execPath,[path.resolve(__dirname,'../qa_operator.js'),
      '--qa-preflight',preflightFile],{
      cwd:path.resolve(__dirname,'..'),
      stdio:['ignore','pipe','pipe']})
    let probeStdout='',probeStderr=''
    for(const [stream,assign] of [[probe.stdout,x=>probeStdout+=x],
      [probe.stderr,x=>probeStderr+=x]]){
      stream.setEncoding('utf8')
      stream.on('data',data=>{
        assign(data)
        if(probeStdout.length+probeStderr.length>4000)probe.kill('SIGKILL')
      })
    }
    const exitCode=await new Promise((resolve,reject)=>{
      const timeout=setTimeout(()=>{
        probe.kill('SIGKILL');reject(Error('Revoked principal preflight hung'))
      },12000)
      probe.once('error',error=>{clearTimeout(timeout);reject(error)})
      probe.once('close',code=>{clearTimeout(timeout);resolve(code)})
    })
    if(exitCode!==2||probeStdout.includes('qa_session_preflight_passed')||
       !probeStderr.includes('Principal revoked or registry unavailable'))
      throw Error('Previously enrolled principal was not denied on a new session')
    if(!fs.readFileSync(path.join(missionDir,'mission.json')).equals(missionBytes)||
       !fs.readFileSync(path.join(depositDir,'deposit.json')).equals(depositBytes)||
       fs.readdirSync(path.join(qaRoot,'spent')).filter(x=>x.endsWith('.used')).length!==usedBefore)
      throw Error('Revoked principal probe changed world-action journals')
    const chestAgain=await owner.openContainer(chestBlock)
    let afterRevokedStock=0
    try{
      for(const slot of chestAgain.slots.slice(0,chestAgain.inventoryStart))
        if(slot?.name==='oak_log')afterRevokedStock+=slot.count
    }finally{chestAgain.close()}
    if(afterRevokedStock!==chestStock)
      throw Error('Revoked preflight altered physical inventory')
    console.log('GUIAIA_STANDALONE_OPERATOR_REAL_FABRIC_QA_EVIDENCE='+JSON.stringify({
      result:'pass',production:false,real_fabric:true,offline_account_identity:false,
      standalone_tty:true,external_qa_signers:true,live_fabric_presence:true,
      signed_remote_witness_on_loopback:true,
      independently_signed_grants:2,spent_nonces:spent.length,
      gathered_oak_log_real:true,physical_chest_oak_log:chestStock,
      mission_receipts:missionResult.receipts.length,
      deposit_receipts:depositResult.receipts.length,
      signed_revocation_durable:true,revocation_checkpoint_sequence:revAfter.sequence,
      post_revocation_preflight_exit:exitCode,post_revocation_preflight_denied:true,
      world_action_journals_unchanged_after_denial:true,
      chest_unchanged_after_denial:afterRevokedStock===chestStock,
      replay_not_attempted:true,teselia_untouched:true
    }))
  }finally{
    if(cli && cli.exitCode===null){
      cli.stdin.write('salir\n')
      await sleep(200)
      if(cli.exitCode===null)cli.kill('SIGTERM')
    }
    try{owner?.end()}catch{}
    try{mission?.close()}catch{}
    try{deposit?.close()}catch{}
    try{registry?.close()}catch{}
    try{await witness.close()}catch{}
    for(const file of [qaRoot,registryRoot,witnessRoot]){
      if(fs.existsSync(file))fs.rmSync(file,{recursive:true,force:true})
    }
  }
}
main().catch(error=>{
  console.error('Standalone real Fabric QA failed: '+String(error?.message||'unknown').slice(0,1000))
  process.exitCode=1
})
